"""Class to model objects and operations for the ID window in the Mosaiq application"""

from interops.libraries.mosaiq.interactions.objects.mosaiq_directory_ids_objects import DirectoryIDsObjects
from interops.libraries.squish_actions import CommonActions

class DirectoryIDs():
    """
    Class used to model a directory IDs window and its operations.
    """
    def __init__(self, window_obj=None) -> None:
        '''
        window_obj is used to distiguish different IDs window (Staff, Location,etc)
        '''
        if window_obj is not None:
            CommonActions.wait_for_object_exists(window_obj)

    def click_button(self, btn:str):
        buttons =  {
            "Close":DirectoryIDsObjects.close_Button,
            "Add":DirectoryIDsObjects.add_Button,
            "Change":DirectoryIDsObjects.change_Button,
            "Delete":DirectoryIDsObjects.delete_Button
        }
        if btn in buttons:
            CommonActions.left_click_object(buttons[btn])
